`timescale 1ns/1ps

// AXI shell test.  Arithmetic vectors are generated by
// model/gen_conv1_vectors.py from the pure-Python conv1 reference.
module tb_axis_shell;
    localparam int K_LEN = 75;
    localparam int FRAME_BEATS = 384;
    localparam int OUT_BEATS = 784;

    logic aclk = 1'b0;
    logic aresetn = 1'b0;
    always #5 aclk = ~aclk;

    logic [11:0] s_axi_awaddr, s_axi_araddr;
    logic [2:0] s_axi_awprot, s_axi_arprot;
    logic s_axi_awvalid, s_axi_awready, s_axi_wvalid, s_axi_wready;
    logic [31:0] s_axi_wdata, s_axi_rdata;
    logic [3:0] s_axi_wstrb;
    logic [1:0] s_axi_bresp, s_axi_rresp;
    logic s_axi_bvalid, s_axi_bready, s_axi_arvalid, s_axi_arready;
    logic s_axi_rvalid, s_axi_rready;

    logic [63:0] s_axis_tdata, m_axis_tdata;
    logic [7:0] s_axis_tkeep, m_axis_tkeep;
    logic s_axis_tlast, s_axis_tvalid, s_axis_tready;
    logic m_axis_tlast, m_axis_tvalid, m_axis_tready;
    logic irq;

    logic [63:0] frame_mem [0:FRAME_BEATS-1];
    logic [63:0] y_mem [0:OUT_BEATS-1];
    logic [7:0] wbank_tmp [0:8191];
    logic [31:0] cfg_bias [0:7];
    logic [17:0] cfg_m0 [0:7];
    logic [5:0] cfg_shift [0:7];
    logic cfg_relu [0:7];

    logic [15:0] lfsr_s = 16'hBEEF;
    logic [15:0] lfsr_m = 16'hACE1;
    int errors = 0;
    int out_seen = 0;
    bit checking = 1'b0;
    bit require_irq_low = 1'b0;
    bit hold_active = 1'b0;
    logic [63:0] hold_data;
    logic [7:0] hold_keep;
    logic hold_last;
    string path;

    accel_axis dut (
        .aclk(aclk), .aresetn(aresetn),
        .s_axi_awaddr(s_axi_awaddr), .s_axi_awprot(s_axi_awprot),
        .s_axi_awvalid(s_axi_awvalid), .s_axi_awready(s_axi_awready),
        .s_axi_wdata(s_axi_wdata), .s_axi_wstrb(s_axi_wstrb),
        .s_axi_wvalid(s_axi_wvalid), .s_axi_wready(s_axi_wready),
        .s_axi_bresp(s_axi_bresp), .s_axi_bvalid(s_axi_bvalid),
        .s_axi_bready(s_axi_bready), .s_axi_araddr(s_axi_araddr),
        .s_axi_arprot(s_axi_arprot), .s_axi_arvalid(s_axi_arvalid),
        .s_axi_arready(s_axi_arready), .s_axi_rdata(s_axi_rdata),
        .s_axi_rresp(s_axi_rresp), .s_axi_rvalid(s_axi_rvalid),
        .s_axi_rready(s_axi_rready),
        .s_axis_tdata(s_axis_tdata), .s_axis_tkeep(s_axis_tkeep),
        .s_axis_tlast(s_axis_tlast), .s_axis_tvalid(s_axis_tvalid),
        .s_axis_tready(s_axis_tready),
        .m_axis_tdata(m_axis_tdata), .m_axis_tkeep(m_axis_tkeep),
        .m_axis_tlast(m_axis_tlast), .m_axis_tvalid(m_axis_tvalid),
        .m_axis_tready(m_axis_tready), .irq(irq)
    );

    task automatic check(input bit ok, input string why);
        if (!ok) begin
            $display("AXIS-SHELL-FAIL: %s", why);
            errors++;
        end
    endtask

    task automatic axi_write(input logic [11:0] addr,
                             input logic [31:0] data);
        @(negedge aclk);
        s_axi_awaddr = addr;
        s_axi_awvalid = 1'b1;
        s_axi_wdata = data;
        s_axi_wstrb = 4'hF;
        s_axi_wvalid = 1'b1;
        s_axi_bready = 1'b0;
        do @(posedge aclk); while (!(s_axi_awready && s_axi_wready));
        @(negedge aclk);
        s_axi_awvalid = 1'b0;
        s_axi_wvalid = 1'b0;
        s_axi_bready = 1'b1;
        do @(posedge aclk); while (!s_axi_bvalid);
        check(s_axi_bresp == 2'b00, $sformatf("BRESP=%0b at %03h", s_axi_bresp, addr));
        @(negedge aclk);
        s_axi_bready = 1'b0;
    endtask

    task automatic axi_read(input logic [11:0] addr,
                            output logic [31:0] data);
        @(negedge aclk);
        s_axi_araddr = addr;
        s_axi_arvalid = 1'b1;
        s_axi_rready = 1'b0;
        do @(posedge aclk); while (!s_axi_arready);
        @(negedge aclk);
        s_axi_arvalid = 1'b0;
        s_axi_rready = 1'b1;
        do @(posedge aclk); while (!s_axi_rvalid);
        data = s_axi_rdata;
        check(s_axi_rresp == 2'b00, $sformatf("RRESP=%0b at %03h", s_axi_rresp, addr));
        @(negedge aclk);
        s_axi_rready = 1'b0;
    endtask

    function automatic logic [15:0] lfsr_next(input logic [15:0] v);
        return {v[14:0], v[15] ^ v[13] ^ v[12] ^ v[10]};
    endfunction

    always @(posedge aclk) begin
        if (!aresetn) begin
            lfsr_s <= 16'hBEEF;
            lfsr_m <= 16'hACE1;
        end else begin
            lfsr_s <= lfsr_next(lfsr_s);
            lfsr_m <= lfsr_next(lfsr_m);
        end
    end

    always @(negedge aclk)
        m_axis_tready = aresetn && (lfsr_m[2:0] != 3'b000);

    always @(posedge aclk) begin
        if (!aresetn) begin
            hold_active <= 1'b0;
        end else begin
            if (require_irq_low)
                check(!irq, "irq asserted while IRQ_EN=0");
            if (hold_active) begin
                check(m_axis_tvalid, "TVALID fell during backpressure");
                check(m_axis_tdata === hold_data, "TDATA changed during backpressure");
                check(m_axis_tkeep === hold_keep, "TKEEP changed during backpressure");
                check(m_axis_tlast === hold_last, "TLAST changed during backpressure");
            end
            hold_active <= m_axis_tvalid && !m_axis_tready;
            if (m_axis_tvalid && !m_axis_tready) begin
                hold_data <= m_axis_tdata;
                hold_keep <= m_axis_tkeep;
                hold_last <= m_axis_tlast;
            end
            if (checking && m_axis_tvalid) begin
                check(m_axis_tkeep == 8'hFF,
                      $sformatf("TKEEP=%02h on beat %0d", m_axis_tkeep, out_seen));
                check(m_axis_tlast == (out_seen == OUT_BEATS-1),
                      $sformatf("TLAST=%0b on beat %0d", m_axis_tlast, out_seen));
            end
            if (checking && m_axis_tvalid && m_axis_tready) begin
                if (out_seen >= OUT_BEATS)
                    check(1'b0, "extra output beat");
                else
                    check(m_axis_tdata === y_mem[out_seen],
                          $sformatf("beat %0d data=%016h expected=%016h",
                                    out_seen, m_axis_tdata, y_mem[out_seen]));
                out_seen++;
            end
        end
    end

    task automatic feed_frame;
        int beat = 0;
        bit accepted = 1'b0;
        while (beat < FRAME_BEATS) begin
            @(negedge aclk);
            if (accepted) begin
                s_axis_tvalid = 1'b0;
                accepted = 1'b0;
            end
            if (!s_axis_tvalid && (lfsr_s[2:0] != 3'b000)) begin
                s_axis_tvalid = 1'b1;
                s_axis_tdata = frame_mem[beat];
                s_axis_tkeep = 8'hFF;
                s_axis_tlast = (beat == FRAME_BEATS-1);
            end
            @(posedge aclk);
            if (s_axis_tvalid && s_axis_tready) begin
                beat++;
                accepted = 1'b1;
            end
        end
        @(negedge aclk);
        s_axis_tvalid = 1'b0;
        s_axis_tlast = 1'b0;
    endtask

    task automatic load_vectors;
        $readmemh("../vectors/c1_frame.mem", frame_mem);
        $readmemh("../vectors/c1_y.mem", y_mem);
        $readmemh("../vectors/c1_cfg_bias.mem", cfg_bias);
        $readmemh("../vectors/c1_cfg_m0.mem", cfg_m0);
        $readmemh("../vectors/c1_cfg_shift.mem", cfg_shift);
        $readmemh("../vectors/c1_cfg_relu.mem", cfg_relu);
    endtask

    task automatic load_weights;
        logic [31:0] value;
        for (int bank = 0; bank < 8; bank++) begin
            path = $sformatf("../vectors/c1_wbank%0d.mem", bank);
            $readmemh(path, wbank_tmp, 0, K_LEN-1);
            axi_write(12'h028, 32'((bank << 16)));
            for (int addr = 0; addr < K_LEN; addr++)
                axi_write(12'h02C, {24'h0, wbank_tmp[addr]});
            axi_read(12'h028, value);
            check(value[18:16] == bank[2:0] && value[12:0] == K_LEN,
                  $sformatf("auto-increment bank %0d W_ADDR=%08h", bank, value));
        end
    endtask

    task automatic configure_pass;
        axi_write(12'h010, {1'b0, 6'd28, 6'd28, 2'd0, 2'd1,
                            3'd5, 3'd5, 9'd3});
        axi_write(12'h018, 32'd3);
        axi_write(12'h01C, 32'd0);
        axi_write(12'h014, {10'b0, 4'd6, 2'b0, 8'd1, 8'd0});
        axi_write(12'h020, 32'd4);
        for (int bank = 0; bank < 8; bank++) begin
            axi_write(12'(12'h040 + 16*bank), cfg_bias[bank]);
            axi_write(12'(12'h044 + 16*bank), {14'h0, cfg_m0[bank]});
            axi_write(12'(12'h048 + 16*bank),
                      {23'h0, cfg_relu[bank], 2'b0, cfg_shift[bank]});
        end
        axi_write(12'h0C0, 32'd1);
    endtask

    task automatic wait_done(output logic [31:0] status);
        int polls = 0;
        do begin
            axi_read(12'h008, status);
            polls++;
        end while (!status[2] && polls < 500000);
        check(status[2] && !status[3] && !status[5],
              $sformatf("STATUS=%08h after %0d polls", status, polls));
        check(out_seen == OUT_BEATS,
              $sformatf("output beats=%0d expected=%0d", out_seen, OUT_BEATS));
    endtask

    logic [31:0] value, status;
    initial begin
        s_axi_awaddr = '0; s_axi_awprot = '0; s_axi_awvalid = 1'b0;
        s_axi_wdata = '0; s_axi_wstrb = '0; s_axi_wvalid = 1'b0;
        s_axi_bready = 1'b0; s_axi_araddr = '0; s_axi_arprot = '0;
        s_axi_arvalid = 1'b0; s_axi_rready = 1'b0;
        s_axis_tdata = '0; s_axis_tkeep = 8'hFF;
        s_axis_tlast = 1'b0; s_axis_tvalid = 1'b0;
        m_axis_tready = 1'b0;
        load_vectors();
        repeat (5) @(negedge aclk);
        aresetn = 1'b1;

        axi_read(12'h000, value);
        check(value == 32'h0001_0005,
              $sformatf("VERSION=%08h expected 00010005", value));
        load_weights();
        configure_pass();

        // IRQ disabled.  A W_DATA write during this pass must neither change
        // memory nor advance W_ADDR; the bit-exact result proves the former.
        axi_write(12'h028, 32'h0000_004A);
        out_seen = 0;
        checking = 1'b1;
        require_irq_low = 1'b1;
        axi_write(12'h004, 32'd1);
        fork feed_frame(); join_none
        while (!s_axis_tready) @(negedge aclk);
        axi_write(12'h02C, 32'h0000_00A5);
        axi_read(12'h028, value);
        check(value == 32'h0000_004A,
              $sformatf("busy W_DATA advanced W_ADDR to %08h", value));
        axi_read(12'h00C, value);
        check(value[3], $sformatf("busy W_DATA ERROR=%02h", value[7:0]));
        axi_write(12'h00C, 32'h0000_0008);
        wait_done(status);
        check(!irq, "irq high after DONE with IRQ_EN=0");
        require_irq_low = 1'b0;
        axi_write(12'h008, 32'd4);
        checking = 1'b0;

        // The same real convolution with IRQ enabled also exercises a fresh
        // LFSR-paced transfer and the DONE W1C interrupt deassertion.
        out_seen = 0;
        checking = 1'b1;
        axi_write(12'h004, 32'd5);
        fork feed_frame(); join_none
        wait_done(status);
        check(irq, "irq low after DONE with IRQ_EN=1");
        axi_write(12'h008, 32'd4);
        check(!irq, "irq stayed high after DONE W1C");
        checking = 1'b0;

        axi_read(12'h00C, value);
        check(value[7:0] == 0, $sformatf("final ERROR=%02h", value[7:0]));
        if (errors == 0)
            $display("PASS tb_axis_shell: v5 weight MMIO, 2x conv bit-exact, AXIS stalls/TKEEP/TLAST, irq");
        else
            $display("AXIS-SHELL-FAIL: %0d errors", errors);
        $finish;
    end

    initial begin
        #2000000000;
        $display("AXIS-SHELL-FAIL: global timeout");
        $finish;
    end
endmodule
